export function FigureElement({
  code = "{{code}}",
  caption = "{{caption}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  return (
    <figure style={{ width: 320, boxSizing: "border-box", margin: 0, font: "14px/1.5 system-ui, sans-serif", background: "#241430", padding: 18, borderRadius: 12, borderLeft: `4px solid ${accent}` }}>
      {variant === "code" ? (
        <pre style={{ margin: "0 0 10px", overflowX: "auto" }}><code style={{ font: "13px/1.5 ui-monospace, monospace", color: "#A8E6C1" }}>{code}</code></pre>
      ) : (
        <blockquote style={{ margin: "0 0 10px", font: "italic 16px/1.5 Georgia, serif", color: "#FAF7F2", paddingLeft: 14, borderLeft: `2px solid ${accent}` }}>{code}</blockquote>
      )}
      <figcaption style={{ margin: 0, fontSize: 12, color: "#FAF7F299" }}>{caption} — a self-contained unit, referenceable from anywhere in the text.</figcaption>
    </figure>
  );
}
